import styled from '@emotion/styled';
import { Paragraph } from 'components/UI';

interface StyledGrowthLeversItemProps {
  $alignItems?: 'default' | 'center';
}

export const StyledGrowthLeversItem = styled('div', {
  shouldForwardProp: (propName) => propName !== '$alignItems',
})<StyledGrowthLeversItemProps>(({ $alignItems = 'default' }) => ({
  display: 'flex',
  flexDirection: 'column',
  padding: '2px 12px',
  height: '64px',
  width: '100%',
  alignItems: $alignItems === 'center' ? 'center' : 'flex-start',
  justifyContent: 'center',
  borderBottom: '1px solid rgba(0, 0, 0, 0.1)',
  '&:last-child': {
    borderBottom: 'none',
  },
}));

export const StyledBigNumberContainer = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'baseline',
  overflow: 'hidden',
  width: '100%',
  minWidth: 0,
});

export const StyledSmallText = styled(Paragraph)({
  color: '#5C5C5C !important',
  whiteSpace: 'nowrap',
  flexShrink: 0,
});

export const StyledVariationText = styled(Paragraph)({
  marginLeft: '4px',
  marginRight: '4px',
  whiteSpace: 'nowrap',
  flexShrink: 0,
});
